-- Project Roost full SQL initializer.
-- Requires the shared `projects` table to already exist.
-- Safe to rerun: schema uses IF NOT EXISTS and seed data uses idempotent upserts.
SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------------------------------
-- 001_create_project_roost_tables.sql
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `project_roost_profiles` (
  `project_id` bigint unsigned NOT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shape` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci,
  `preview_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `production_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`project_id`),
  UNIQUE KEY `project_roost_profiles_slug_unique` (`slug`),
  KEY `project_roost_profiles_category_index` (`category`),
  KEY `project_roost_profiles_shape_index` (`shape`),
  CONSTRAINT `project_roost_profiles_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `project_roost_review_snapshots` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `project_id` bigint unsigned NOT NULL,
  `reviewed_at` datetime NOT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frontend_score` decimal(4,1) DEFAULT NULL,
  `backend_score` decimal(4,1) DEFAULT NULL,
  `security_score` decimal(4,1) DEFAULT NULL,
  `overall_score` decimal(4,1) DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `priority_fix` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_roost_reviews_source_unique` (`project_id`, `source`, `source_hash`),
  KEY `project_roost_reviews_reviewed_at_index` (`reviewed_at`),
  KEY `project_roost_reviews_overall_index` (`overall_score`),
  CONSTRAINT `project_roost_reviews_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `project_roost_risk_assessments` (
  `project_id` bigint unsigned NOT NULL,
  `severity` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `auth_risk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_risk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `env_risk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ownership_risk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`project_id`),
  KEY `project_roost_risks_severity_index` (`severity`),
  CONSTRAINT `project_roost_risks_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `project_roost_tasks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `project_id` bigint unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `effort` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `impact` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_roost_tasks_import_unique` (`project_id`, `source`, `source_hash`),
  KEY `project_roost_tasks_status_index` (`status`),
  KEY `project_roost_tasks_priority_index` (`priority`),
  CONSTRAINT `project_roost_tasks_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `project_roost_imports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `imported_at` datetime NOT NULL,
  `project_count` int unsigned NOT NULL,
  `review_count` int unsigned NOT NULL,
  `task_count` int unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_roost_imports_source_hash_unique` (`source`, `source_hash`),
  KEY `project_roost_imports_imported_at_index` (`imported_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 002_create_project_roost_deployments.sql
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `project_roost_deployments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `project_id` bigint unsigned DEFAULT NULL,
  `project_slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `environment` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `frontend_deployed` tinyint(1) NOT NULL DEFAULT '0',
  `backend_deployed` tinyint(1) NOT NULL DEFAULT '0',
  `destination_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remote_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_mode` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `git_commit` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actor` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `deployed_at` datetime NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `project_roost_deployments_project_environment_index` (`project_slug`, `environment`),
  KEY `project_roost_deployments_deployed_at_index` (`deployed_at`),
  KEY `project_roost_deployments_project_id_fk` (`project_id`),
  CONSTRAINT `project_roost_deployments_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 005_create_project_roost_bug_reports.sql
-- -----------------------------------------------------------------------------
-- Untrusted, public player-submitted bug reports (moderation queue). See migration
-- 005_create_project_roost_bug_reports.sql for details.
CREATE TABLE IF NOT EXISTS `project_roost_bug_reports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `project_id` bigint unsigned DEFAULT NULL,
  `project_slug` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(140) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact` varchar(190) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `game_version` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(400) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new',
  `promoted_task_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `project_roost_bug_reports_status_index` (`status`),
  KEY `project_roost_bug_reports_project_index` (`project_id`),
  KEY `project_roost_bug_reports_ip_created_index` (`ip_hash`, `created_at`),
  CONSTRAINT `project_roost_bug_reports_project_id_fk`
    FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 003_add_project_roost_display_name.sql
-- -----------------------------------------------------------------------------
SET @project_roost_display_name_exists := (
  SELECT COUNT(*)
  FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'project_roost_profiles'
    AND COLUMN_NAME = 'display_name'
);

SET @project_roost_display_name_sql := IF(
  @project_roost_display_name_exists = 0,
  'ALTER TABLE `project_roost_profiles` ADD COLUMN `display_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL AFTER `slug`',
  'SELECT 1'
);

PREPARE project_roost_display_name_stmt FROM @project_roost_display_name_sql;
EXECUTE project_roost_display_name_stmt;
DEALLOCATE PREPARE project_roost_display_name_stmt;

UPDATE `project_roost_profiles` pr
INNER JOIN `projects` p ON p.id = pr.project_id
SET pr.display_name = p.title
WHERE pr.display_name IS NULL OR pr.display_name = '';

-- -----------------------------------------------------------------------------
-- 004_clean_shared_project_catalog.sql
-- -----------------------------------------------------------------------------
UPDATE `project_roost_profiles`
SET `display_name` = CASE `slug`
  WHEN 'adventcon' THEN 'Adventure Story Generator'
  WHEN 'anime_prompt_gen' THEN 'Anime Prompt Generator'
  WHEN 'isitdoneyet' THEN 'Is It Done Yet?'
  WHEN 'kemo_sim' THEN 'Kemo Simulator'
  WHEN 'name_generator' THEN 'Name Generator API'
  WHEN 'writers_studio' THEN 'Writers Studio'
  ELSE `display_name`
END,
`updated_at` = NOW()
WHERE `slug` IN (
  'adventcon',
  'anime_prompt_gen',
  'isitdoneyet',
  'kemo_sim',
  'name_generator',
  'writers_studio'
);

UPDATE `projects` stale
LEFT JOIN `project_roost_profiles` own_profile ON own_profile.`project_id` = stale.`id`
INNER JOIN `project_roost_profiles` profiled_project
  ON profiled_project.`project_id` <> stale.`id`
  AND (
    LOWER(TRIM(BOTH '/' FROM REPLACE(stale.`path`, CHAR(92), '/'))) = profiled_project.`slug`
    OR LOWER(TRIM(BOTH '/' FROM REPLACE(stale.`path`, CHAR(92), '/'))) LIKE CONCAT('%/', profiled_project.`slug`)
    OR LOWER(TRIM(BOTH '/' FROM REPLACE(stale.`path`, CHAR(92), '/'))) LIKE CONCAT('%/', profiled_project.`slug`, '/%')
  )
SET stale.`hidden` = 1,
    stale.`show_on_homepage` = 0,
    stale.`updated_at` = NOW()
WHERE own_profile.`project_id` IS NULL
  AND (stale.`hidden` <> 1 OR stale.`show_on_homepage` <> 0);

UPDATE `projects` stale
SET stale.`hidden` = 1,
    stale.`show_on_homepage` = 0,
    stale.`updated_at` = NOW()
WHERE (
    LOWER(REPLACE(REPLACE(stale.`title`, ' ', '_'), '-', '_')) = 'litrpg_studio'
    OR LOWER(TRIM(BOTH '/' FROM REPLACE(stale.`path`, CHAR(92), '/'))) LIKE '%/litrpg_studio'
    OR LOWER(TRIM(BOTH '/' FROM REPLACE(stale.`path`, CHAR(92), '/'))) LIKE '%/litrpg_studio/%'
  )
  AND EXISTS (
    SELECT 1
    FROM `project_roost_profiles` replacement
    WHERE replacement.`slug` = 'writers_studio'
  )
  AND (stale.`hidden` <> 1 OR stale.`show_on_homepage` <> 0);

UPDATE `projects` replacement
INNER JOIN `project_roost_profiles` replacement_profile ON replacement_profile.`project_id` = replacement.`id`
SET replacement.`hidden` = 0,
    replacement.`show_on_homepage` = 1,
    replacement.`updated_at` = NOW()
WHERE replacement_profile.`slug` = 'writers_studio'
  AND (replacement.`hidden` <> 0 OR replacement.`show_on_homepage` <> 1);

-- -----------------------------------------------------------------------------
-- 008_move_comfyui_to_local.sql
-- -----------------------------------------------------------------------------
-- Keep the ComfyUI catalog entry aligned with its move out of the apps workspace.
-- REPLACE preserves the drive and parent workspace used by each environment.

UPDATE `projects`
SET `path` = REPLACE(`path`, '\\apps\\comfyui', '\\local\\comfyui'),
    `updated_at` = NOW()
WHERE `title` = 'comfyui'
  AND `path` LIKE '%\\apps\\comfyui';

